mapper.select:
SELECT count(*)
  FROM sales_order o
 WHERE o.partner_id = #{partnerId}

   AND o.status = #{status}

SELECT o.id, o.order_no, o.status, o.total_amount, (SELECT count(*) FROM sales_order_item i WHERE i.order_id = o.id) AS item_count, (SELECT p.name FROM sales_order_item i JOIN product p ON p.id = i.product_id WHERE i.order_id = o.id ORDER BY i.line_no LIMIT 1) AS first_product_name, o.ordered_at FROM sales_order o WHERE o.partner_id = #{partnerId}
AND o.status = #{status}
ORDER BY o.ordered_at DESC, o.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT o.id, o.order_no, o.partner_id, p.name AS partner_name, o.partner_grade_code,
       o.status, o.total_amount, o.ordered_at, o.approved_at, o.shipped_at
  FROM sales_order o
  JOIN partner p ON p.id = o.partner_id
 WHERE o.id = #{orderId}

   AND o.partner_id = #{partnerId}

mapper.update:
UPDATE sales_order
   SET status  = 'CANCELED',
       version = version + 1
 WHERE id = #{orderId}
   AND partner_id = #{partnerId}
   AND status = 'REQUESTED'
